// reproduce.js
const express = require('express');
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

// Collect any User-Agent headers we see
const seenUserAgents = [];

// Simple HTTP server that logs UA on each request
const app = express();
app.get('/', (req, res) => {
  const ua = req.get('User-Agent');
  console.log('Incoming request UA:', ua);
  seenUserAgents.push(ua);
  res.send(`<!doctype html><html><head><title>Test</title></head><body>
    <h1>Hello, Lighthouse!</h1>
  </body></html>`);
});

const server = app.listen(8080, async () => {
  console.log('Server listening on http://localhost:8080');

  // Launch Chrome via chrome-launcher
  const chrome = await chromeLauncher.launch({
    chromeFlags: ['--headless', '--no-sandbox']
  });

  const options = {
    port: chrome.port,
    logLevel: 'info',
    output: 'json',
    // Emulate a mobile form factor (Nexus 5)
    emulatedFormFactor: 'mobile',
    // You can also pass network throttling settings here if you like
  };

  try {
    const runnerResult = await lighthouse('http://localhost:8080', options);
    const lhr = runnerResult.lhr;

    // The UA that Lighthouse prints in its Runtime settings
    const reportedUA = lhr.runtimeSettings.userAgent;

    console.log('\n=== Lighthouse report UA ===');
    console.log(reportedUA);

    console.log('\n=== User-Agent headers seen by server ===');
    seenUserAgents.forEach((ua, i) => console.log(`${i + 1}: ${ua}`));

    console.log(`\nReport generated by Lighthouse ${lhr.lighthouseVersion}`);
  } catch (err) {
    console.error(err);
  } finally {
    await chrome.kill();
    server.close();
  }
});
